'use strict';
const panel = document.getElementById('demo-panel');
const tabs = [...document.querySelectorAll('[data-view]')];
const sampleEntries = [{date:'2026-10-08',title:'留一点时间给自己',text:'今天，给自己留了一个慢慢吃早餐的早晨。\n\n窗外的阳光刚刚好。把想做的事记下来，一件一件来。\n\n原来普通的一天，也有值得收藏的片刻。'}, {date:'2026-10-07',title:'散步时的小发现',text:'下班绕了一点路，发现街角开了一家小书店。\n\n没有特别的计划，只想翻几页书，再慢慢走回家。'}, {date:'2026-10-05',title:'十月的小计划',text:'读完一本书。\n多去公园走走。\n记下每天一件开心的小事。\n\n不着急，把日子过好。'}];
let currentView='calendar'; let stickyText='今天的小提醒：\n记得抬头，看看窗外。'; let stickyColor='yellow';
const colors={yellow:'#fff0ad',blue:'#d7eaf0',green:'#e0ebd6',pink:'#f3dce4'};
function renderCalendar(){
 const cells=Array.from({length:42},(_,i)=>{const raw=i-2; const day=raw<1?raw+30:raw>31?raw-31:raw; const outside=raw<1||raw>31; const journal=!outside&&[5,7,8].includes(day);return '<button class="demo-day '+(outside?'is-outside ':'')+(journal?'is-journal':'')+'" data-day="'+day+'" data-month="'+(raw<1?9:raw>31?11:10)+'" aria-label="预览 '+(raw<1?9:raw>31?11:10)+' 月 '+day+' 日" aria-pressed="'+(raw===8)+'"><span class="demo-day-heading">'+day+(journal?'<small>日记</small>':'')+'</span>'+(!outside&&day===8?'<span class="demo-event">17:30 去公园走走</span>':'')+'</button>';}).join('');
 panel.innerHTML='<div class="demo-calendar-layout"><div class="demo-calendar"><div class="demo-month"><span class="demo-month-nav">◀ &nbsp; <strong>2026 年 10 月</strong> &nbsp; ▶ <span class="demo-today">今天</span></span><span>全部标签</span></div><div class="demo-week">'+['周一','周二','周三','周四','周五','周六','周日'].map(day=>'<span>'+day+'</span>').join('')+'</div><div class="demo-days">'+cells+'</div></div><aside class="demo-aside"><h4 id="demo-date">10 月 8 日</h4><p class="demo-aside-meta">1 个事项 · 1 个待完成</p><label class="demo-task"><input type="checkbox" aria-label="完成示例事项"><span>去公园走走<small>17:30 · 留一点空闲</small></span></label></aside></div>';
 panel.querySelectorAll('[data-day]').forEach(button=>button.addEventListener('click',()=>{panel.querySelectorAll('[data-day]').forEach(day=>day.setAttribute('aria-pressed',String(day===button)));document.getElementById('demo-date').textContent=button.dataset.month+' 月 '+button.dataset.day+' 日';}));
}
function renderJournal(){
 panel.innerHTML='<div class="demo-journal"><aside class="demo-directory"><span>分类目录 / 日记</span>'+sampleEntries.map((entry,i)=>'<button data-entry="'+i+'" aria-pressed="'+(i===0)+'">'+entry.date.slice(5).replace('-','.')+'<br>'+entry.title+'</button>').join('')+'</aside><article class="demo-reading"><h4></h4><time></time><p></p></article></div>';
 const select=index=>{const entry=sampleEntries[index];panel.querySelector('.demo-reading h4').textContent=entry.title;panel.querySelector('time').textContent=entry.date;panel.querySelector('.demo-reading p').textContent=entry.text;panel.querySelectorAll('[data-entry]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.entry)===index)));};select(0);panel.querySelectorAll('[data-entry]').forEach(button=>button.addEventListener('click',()=>select(Number(button.dataset.entry))));
}
function renderSticky(){
 panel.innerHTML='<div class="demo-sticky-view"><div class="demo-sticky-note"><span>10 月 8 日 · 一点小事</span><textarea aria-label="试写便签（仅本页示例，不会保存）" maxlength="500"></textarea></div><div class="demo-sticky-controls"><p>给此刻，选一个颜色。</p><div class="color-options" role="group" aria-label="示例便签颜色">'+Object.entries(colors).map(([name,color])=>'<button data-color="'+name+'" aria-pressed="'+(stickyColor===name)+'" aria-label="'+({yellow:'黄色',blue:'蓝色',green:'绿色',pink:'粉色'}[name])+'" style="background:'+color+'"></button>').join('')+'</div><span>可以在左边试着写两句。<br>示例不保存，刷新后会还原。</span></div></div>';
 panel.querySelector('textarea').value=stickyText;panel.querySelector('.demo-sticky-note').style.background=colors[stickyColor];panel.querySelector('textarea').addEventListener('input',event=>{stickyText=event.target.value;});panel.querySelectorAll('[data-color]').forEach(button=>button.addEventListener('click',()=>{stickyColor=button.dataset.color;panel.querySelector('.demo-sticky-note').style.background=colors[stickyColor];panel.querySelectorAll('[data-color]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));}));
}
function showView(view){currentView=view;tabs.forEach(tab=>{const selected=tab.dataset.view===view;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;});panel.setAttribute('aria-labelledby','tab-'+view);document.querySelectorAll('.product-toolbar span').forEach((span,i)=>span.classList.toggle('product-active',view==='journal'?i===1:i===0));({calendar:renderCalendar,journal:renderJournal,sticky:renderSticky})[view]();}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>showView(tab.dataset.view));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();tabs[next].focus();showView(tabs[next].dataset.view);});});showView(currentView);
const artwork=document.querySelector('.stationery-art');artwork.addEventListener('load',()=>{artwork.hidden=false;document.querySelector('.hero').classList.add('art-ready');});if(artwork.complete&&artwork.naturalWidth){artwork.hidden=false;document.querySelector('.hero').classList.add('art-ready');}
let releases={packages:{}};let architecture='arm64';
function applyPackage(link,info,pkg){if(pkg&&pkg.url&&pkg.verified===true&&pkg.url.startsWith('https://github.com/ziyu1617/pf-notes/releases/download/')){link.href=pkg.url;link.removeAttribute('aria-disabled');link.textContent='下载 '+(pkg.label||'安装包');info.textContent=[pkg.version,pkg.requirements,pkg.size].filter(Boolean).join(' · ');}else{link.removeAttribute('href');link.setAttribute('aria-disabled','true');link.textContent='安装包准备中';info.textContent=pkg?.status||'完成构建验证后开放下载';}}
function updateDownloads(){applyPackage(document.getElementById('download-mac'),document.getElementById('mac-info'),releases.packages['macos-'+architecture]);document.getElementById('release-notice').textContent=releases.notice||'首批安装包正在准备中。你也可以从 GitHub 获取源代码。';}
document.querySelectorAll('[data-arch]').forEach(button=>button.addEventListener('click',()=>{architecture=button.dataset.arch;document.querySelectorAll('[data-arch]').forEach(option=>option.setAttribute('aria-pressed',String(option===button)));updateDownloads();}));
fetch('downloads.json',{cache:'no-cache'}).then(response=>{if(!response.ok)throw new Error('Unavailable');return response.json();}).then(data=>{if(data&&typeof data.packages==='object'){releases=data;updateDownloads();}}).catch(()=>{document.getElementById('release-notice').textContent='暂时无法获取下载信息，请到 GitHub 的版本页面查看。';});

const previewViewport=document.querySelector(".product-viewport");
new ResizeObserver(entries=>{previewViewport.style.setProperty("--preview-scale",String(entries[0].contentRect.width/1200));}).observe(previewViewport);
